var gl, canvas, program;
var points=[];
var normals=[];
var objTans=[];

var near = -10;
var far = 10;
var radius = 1.5;
var postheta  = [0.0,0.0,0.0];
var lightheta  = [0.0,0.0,0.0];
var posthetaLoc, lighthetaLoc;

var dr = 5.0 * Math.PI/180.0;
var pAxis = -1;
var lAxis = -1;

var left = -3.0;
var right = 3.0;
var ytop = 3.0;
var bottom = -3.0;

var eye = vec3(0.0,0.0,-1.0);
var at = vec3(0.0,0.0,0.0);
var up = vec3(0.0,1.0,0.0);

var lightPosition = vec4(-10.0, 0.0, 0.0, 1.0 );
var lightAmbient = vec4(0.2, 0.2, 0.2, 1.0 );
var lightDiffuse = vec4( 1.0, 1.0, 1.0, 1.0 );
var lightSpecular = vec4( 1.0, 1.0, 1.0, 1.0 );

var materialAmbient = vec4( 1.0, 1.0, 1.0, 1.0 );
var materialDiffuse = vec4( 1.0, 1.0, 1.0, 1.0 );
var materialSpecular = vec4( 1.0, 1.0, 1.0, 1.0 );
var materialShininess = 20.0;

var modelViewMatrix, projectionMatrix;
var modelViewMatrixLoc, projectionMatrixLoc;

var index = 0;

var vertices = [vec4(0.0,1.0,0.0,1.0),//무게 중심이 xyz(0,0,0)이고 각 꼭짓점에서 무게중심까지의 거리가 1인 정사면체;
    vec4(0.0, -0.333333, 0.942809, 1.0),
    vec4(-0.816497, -0.333333, -0.471405, 1.0),
    vec4(0.816497, -0.333333, -0.471405, 1.0)];



var normalst = new Array()//각 x,y 높이차
    for (var i=0; i<512; i++)  normalst[i] = new Array();
    for (var i=0; i<512; i++) for ( var j = 0; j < 512; j++)
        normalst[i][j] = new Array();
    for (var i=0; i<512; i++) for ( var j = 0; j < 512; j++) {
        normalst[i][j][0] = heightMap[i][j]-heightMap[i+1][j];
        normalst[i][j][1] = heightMap[i][j]-heightMap[i][j+1];
        normalst[i][j][2] = 1;
    }
for (var i=0; i<512; i++) for (var j=0; j<512; j++) {//정규화 후 rgb에 fit하게 값을 수정 
       var d = 0;
       for(k=0;k<3;k++) d+=normalst[i][j][k]*normalst[i][j][k];
       d = Math.sqrt(d);
       for(k=0;k<3;k++) normalst[i][j][k]= 0.5*normalst[i][j][k]/d + 0.5;
    }

var normalMap = new Uint8Array(3*512*512);

    for ( var i = 0; i < 512; i++ )
        for ( var j = 0; j < 512; j++ )
           for(var k =0; k<3; k++)
                normalMap[3*512*i+3*j+k] = 255*normalst[i][j][k];


//var vertices2 = [vec4()]
var texCoords = [];
//-----------------------------------------------------------
var earthImage = new Image();

var earthImagePromise = loadImage(earthImage);

earthImage.src = "data:image/png;base64,";

function loadImage(img) {
    return new Promise((resolve, reject) => {
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error("이미지 로딩 실패"));
    });
}
//------------------------------------------------------------
function configureTexture(img, normalImg){
    var texture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, texture);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, gl.RGB, gl.UNSIGNED_BYTE, img);
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.uniform1i(gl.getUniformLocation(program, "texture"), 0);

    var normalTexture = gl.createTexture();
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, normalTexture);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGB, 512, 512, 0, gl.RGB, gl.UNSIGNED_BYTE, normalImg);
    gl.generateMipmap(gl.TEXTURE_2D);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.NEAREST_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.NEAREST);
    gl.uniform1i(gl.getUniformLocation(program, "normalMap"), 1);
}

function coord2latitude(y){
    return Math.asin(y);
}
function coord2longitude(x,z){
    return Math.atan2(-z,x);
}
function vertex2tex(v){
    let x = v[0]; let y = v[1]; let z = v[2];
    return vec2((coord2longitude(x,z)+Math.PI)/(2.0*Math.PI),(coord2latitude(y)+Math.PI/2.0)/Math.PI)
}

function triangle(a,b,c){
    points.push(a);
    points.push(b);
    points.push(c);

    normals.push(a[0],a[1],a[2],0.0);
    normals.push(b[0],b[1],b[2],0.0);
    normals.push(c[0],c[1],c[2],0.0);

    let longtheta = [coord2longitude(a[0],a[3]),coord2longitude(b[0],b[3]),coord2longitude(c[0],c[3])];
    objTans.push( -Math.cos(longtheta[0]), 0.0,Math.sin(longtheta[0]), 0.0 );
    objTans.push( -Math.cos(longtheta[1]), 0.0,Math.sin(longtheta[1]), 0.0 );
    objTans.push( -Math.cos(longtheta[2]), 0.0,Math.sin(longtheta[2]), 0.0 );

    texCoords.push(vertex2tex(a));
    texCoords.push(vertex2tex(b));
    texCoords.push(vertex2tex(c));

    index += 3;
}

function divideTriangle(a,b,c,count){
    if(count > 0){
        var ab = mix(a, b, 0.5);
        var bc = mix(b, c, 0.5);
        var ca = mix(c, a, 0.5);

        ab = normalize(ab,true);
        bc = normalize(bc,true);//정규화를 통해 원점에서 해당하는 점을 가리키는 벡터의 방향으로 원점과의 거리가 1인 위치로 이동
        ca = normalize(ca,true);

        divideTriangle(a, ab, ca, count - 1);
        divideTriangle(ab, b, bc, count - 1);
        divideTriangle(ca, bc, c, count - 1);
        divideTriangle(ab, bc, ca, count - 1);
    }
    else{
        triangle(a,b,c);
    }
}

function tetrahedron(a,b,c,d,n){
    divideTriangle(a,b,c,n);
    divideTriangle(a,c,d,n);
    divideTriangle(a,d,b,n);
    divideTriangle(d,c,b,n);
}

window.onload = async function init(){
    canvas = document.getElementById("gl-canvas");
    gl = WebGLUtils.setupWebGL(canvas);
    if(!gl){alert("WebGL failed")}

    try {
        await earthImagePromise;
    } catch (error) {
        console.error(error);
        return;
    }
    
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(1.0,1.0,1.0,1.0);

    gl.enable(gl.DEPTH_TEST);

    program = initShaders(gl,"vertex-shader","fragment-shader");
    gl.useProgram(program);

    var ambientProduct = mult(lightAmbient, materialAmbient);
    var diffuseProduct = mult(lightDiffuse, materialDiffuse);
    var specularProduct = mult(lightSpecular, materialSpecular);

    tetrahedron(vertices[0], vertices[1], vertices[2], vertices[3], 8);

    
    var nBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, nBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, flatten(normals), gl.STATIC_DRAW);
    
    var vNormal = gl.getAttribLocation(program, "vNormal");
    gl.vertexAttribPointer(vNormal, 4, gl.FLOAT, false, 0, 0);
    gl.enableVertexAttribArray(vNormal);

    var vBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, flatten(points), gl.STATIC_DRAW);

    var vPosition = gl.getAttribLocation(program, "vPosition");
    gl.vertexAttribPointer(vPosition, 4, gl.FLOAT, false, 0, 0);
    gl.enableVertexAttribArray(vPosition);

    var TBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, TBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, flatten(objTans), gl.STATIC_DRAW);
    
    var objTangent = gl.getAttribLocation(program, "objTangent");
    gl.vertexAttribPointer(objTangent, 4, gl.FLOAT, false, 0, 0);
    gl.enableVertexAttribArray(objTangent);

    var texBuffer = gl.createBuffer();
    gl.bindBuffer( gl.ARRAY_BUFFER, texBuffer);
    gl.bufferData( gl.ARRAY_BUFFER, flatten(texCoords), gl.STATIC_DRAW );

    var vTexCoord = gl.getAttribLocation( program, "vTexCoord" );
    gl.enableVertexAttribArray( vTexCoord );
    gl.vertexAttribPointer( vTexCoord, 2, gl.FLOAT, false, 0, 0);

    configureTexture(earthImage, normalMap);


    posthetaLoc = gl.getUniformLocation(program, "postheta");
    lighthetaLoc = gl.getUniformLocation(program, "lightheta");

    modelViewMatrixLoc = gl.getUniformLocation( program, "modelViewMatrix" );
    projectionMatrixLoc = gl.getUniformLocation( program, "projectionMatrix" );

    document.getElementById("Button0").onclick = function(){pAxis = -1};
    document.getElementById("Button1").onclick = function(){lAxis = -1};
    document.getElementById("Button2").onclick = function(){pAxis = 0;};
    document.getElementById("Button3").onclick = function(){pAxis = 1;};
    document.getElementById("Button4").onclick = function(){pAxis = 2;};
    document.getElementById("Button5").onclick = function(){lAxis = 0;};
    document.getElementById("Button6").onclick = function(){lAxis = 1;};
    document.getElementById("Button7").onclick = function(){lAxis = 2;};
    

    
    

    gl.uniform4fv( gl.getUniformLocation(program,
       "ambientProduct"),flatten(ambientProduct) );
    gl.uniform4fv( gl.getUniformLocation(program,
       "diffuseProduct"),flatten(diffuseProduct) );
    gl.uniform4fv( gl.getUniformLocation(program,
       "specularProduct"),flatten(specularProduct) );
    gl.uniform4fv( gl.getUniformLocation(program,
       "lightPosition"),flatten(lightPosition) );
    gl.uniform1f( gl.getUniformLocation(program,
       "shininess"),materialShininess );


    render();
}


function render(){
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    if(pAxis > -1)
        postheta[pAxis] += 2.0;
    if(lAxis > -1)
        lightheta[lAxis] += 2.0;
    modelViewMatrix = lookAt(eye, at, up);
    projectionMatrix = ortho(left, right, bottom, ytop, near, far);

    gl.uniform3fv(posthetaLoc, flatten(postheta));
    gl.uniform3fv(lighthetaLoc, flatten(lightheta));
    gl.uniformMatrix4fv(modelViewMatrixLoc, false, flatten(modelViewMatrix) );
    gl.uniformMatrix4fv(projectionMatrixLoc, false, flatten(projectionMatrix) );

    
    gl.drawArrays( gl.TRIANGLES, 0, index );
    
    requestAnimationFrame(render);
}

